cat << 'EOF' > /tmp/parse_binlog.cs
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("/tmp/sv-783cb5d6c34c4d97a284956524e7fb0c/build.binlog");
Console.WriteLine($"Build Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors
var errors = new List<(string project, string code, string message, string file, int line)>();
build.VisitAllChildren<Error>(error => {
    var project = "";
    var node = error.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((project, error.Code ?? "", error.Message ?? "", error.File ?? "", error.LineNumber));
});

Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine();

// Group by project
var byProject = errors.GroupBy(e => e.project).OrderBy(g => g.Key);
foreach (var grp in byProject) {
    Console.WriteLine($"=== Project: {grp.Key} ===");
    foreach (var e in grp) {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
    Console.WriteLine();
}
EOF
